_CPP_SRC = r'''
torch::Tensor gn_silu_nhwc(torch::Tensor in_nhwc, torch::Tensor gamma, torch::Tensor beta,
                           double eps, int64_t G, int64_t B, int64_t C, int64_t P);
torch::Tensor gn_silu_res_nchw(torch::Tensor in_nhwc, torch::Tensor res_nchw,
                               torch::Tensor gamma, torch::Tensor beta,
                               double eps, int64_t G, int64_t B, int64_t C, int64_t P);
torch::Tensor to_nhwc(torch::Tensor x);
torch::Tensor weight_to_nhwc(torch::Tensor w);
'''

_ext = load_inline(
    name="vae_resblock_gn_silu_v2",
    cpp_sources=_CPP_SRC,
    cuda_sources=_CUDA_SRC,
    functions=["gn_silu_nhwc", "gn_silu_res_nchw", "to_nhwc", "weight_to_nhwc"],
    verbose=False,
    extra_cflags=["-O3", "-std=c++20"],
    extra_cuda_cflags=[
        "-O3",
        "-std=c++20",
        "--expt-relaxed-constexpr",
        "-lineinfo",
        "-gencode=arch=compute_120,code=sm_120",
    ],
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    @staticmethod
    def _cl_weight(w):
        # NOTE: no caching across calls - tensor addresses get recycled by the
        # caching allocator, so a data_ptr-keyed cache can silently return a
        # stale weight. The copy is ~2MB and costs a few microseconds.
        if w.is_contiguous(memory_format=torch.channels_last):
            return w
        if (w.dtype == torch.float32 and w.dim() == 4
                and w.is_contiguous()
                and w.size(2) * w.size(3) == 9
                and w.size(1) * 9 * 4 <= 48 * 1024):
            return _ext.weight_to_nhwc(w)
        return w.contiguous(memory_format=torch.channels_last)

    def forward(self, x, conv1_weight, norm1_weight, norm1_bias,
                conv2_weight, norm2_weight, norm2_bias, eps):
        if isinstance(eps, torch.Tensor):
            eps = float(eps.item())
        num_groups = 32

        assert x.dtype == torch.float32, "float32 only"
        res = x if x.is_contiguous() else x.contiguous()

        B, C, H, W = res.shape
        P = H * W

        w1 = self._cl_weight(conv1_weight)
        w2 = self._cl_weight(conv2_weight)

        # custom tiled NCHW -> NHWC transpose of the activation (replaces the
        # implicit ATen elementwise_kernel copy conv1 would otherwise insert)
        xn = _ext.to_nhwc(res)

        # conv #1 : cuDNN, channels_last output (no layout transposes inserted)
        o = F.conv2d(xn, w1, None, 1, 1)
        if not o.is_contiguous(memory_format=torch.channels_last):
            o = o.contiguous(memory_format=torch.channels_last)

        # fused GroupNorm + SiLU (NHWC -> NHWC)
        o = _ext.gn_silu_nhwc(o, norm1_weight.contiguous(), norm1_bias.contiguous(),
                              eps, num_groups, B, C, P)

        # conv #2
        o = F.conv2d(o, w2, None, 1, 1)
        if not o.is_contiguous(memory_format=torch.channels_last):
            o = o.contiguous(memory_format=torch.channels_last)

        # fused GroupNorm + SiLU + residual + NHWC->NCHW restore
        out = _ext.gn_silu_res_nchw(o, res, norm2_weight.contiguous(), norm2_bias.contiguous(),
                                    eps, num_groups, B, C, P)
        return out
